<template>
  <div class="page detail-page" v-loading="loading">
    <div class="page-header">
      <div><div class="page-title">施工流程详情</div><div class="page-subtitle">{{ row?.workflowNo || '-' }} · {{ row?.permitNo || '-' }}</div></div>
      <div class="actions">
        <el-button @click="router.push('/construction')">返回列表</el-button>
        <el-button v-if="row?.publicToken" type="primary" @click="router.push(`/construction/${row.id}/permit`)">查看/打印许可证</el-button>
        <el-button v-if="canRequestAcceptance && ['IN_PROGRESS','REJECTED'].includes(row?.status||'')" type="success" @click="acceptanceVisible=true">申请验收</el-button>
        <el-button v-if="canManageAcceptance && row?.status==='PENDING_ACCEPTANCE'" type="success" @click="decisionVisible=true">填写验收结果</el-button>
        <el-button v-if="['IN_PROGRESS','REJECTED'].includes(row?.status||'') && canCreate" @click="cancel">取消流程</el-button>
        <el-button v-if="canDelete" type="warning" @click="reset">复位</el-button><el-button v-if="canDelete" type="danger" @click="remove">彻底删除</el-button>
      </div>
    </div>
    <el-alert v-if="row" :title="effectHint" :type="row.status==='ARCHIVED'?'success':'info'" show-icon :closable="false" class="effect-hint" />
    <el-card v-if="row" shadow="never">
      <template #header><div class="card-title"><span>申请事项</span><el-tag :type="statusType(row.status)">{{ statusLabel(row.status) }}</el-tag></div></template>
      <el-descriptions :column="descriptionColumns" border>
        <el-descriptions-item label="许可证编号">{{ row.permitNo || '-' }}</el-descriptions-item><el-descriptions-item label="申请类型">{{ typeLabel(row.workflowType) }}</el-descriptions-item><el-descriptions-item label="施工位置">{{ locationLabel }}</el-descriptions-item>
        <el-descriptions-item label="当前铺位状态">{{ stallStatusLabel(row.currentStallStatus) }}</el-descriptions-item><el-descriptions-item label="施工开始时间">{{ formatDateTime(row.constructionStartTime) }}</el-descriptions-item><el-descriptions-item label="施工结束时间">{{ formatDateTime(row.constructionEndTime) }}</el-descriptions-item>
        <el-descriptions-item label="申请人">{{ row.applicantName || '-' }}</el-descriptions-item><el-descriptions-item label="提交时间">{{ formatDateTime(row.submittedAt) }}</el-descriptions-item><el-descriptions-item label="归档时间">{{ formatDateTime(row.archivedAt) }}</el-descriptions-item><el-descriptions-item label="备注" :span="descriptionColumns">{{ row.remark || '-' }}</el-descriptions-item>
      </el-descriptions>
    </el-card>
    <el-card v-if="row" shadow="never"><template #header>商户与施工方</template><el-descriptions :column="descriptionColumns" border>
      <el-descriptions-item label="商户名称">{{ row.merchantName }}</el-descriptions-item><el-descriptions-item label="商户负责人">{{ row.merchantPrincipalName }}</el-descriptions-item><el-descriptions-item label="联系电话">{{ row.merchantPrincipalPhone }}</el-descriptions-item>
      <el-descriptions-item label="施工公司">{{ row.constructionCompanyName }}</el-descriptions-item><el-descriptions-item label="施工负责人">{{ row.constructionPrincipalName }}</el-descriptions-item><el-descriptions-item label="负责人电话">{{ row.constructionPrincipalPhone }}</el-descriptions-item>
      <el-descriptions-item label="物业部工程专员">{{ row.propertyEngineerName }}</el-descriptions-item><el-descriptions-item label="工程专员电话">{{ row.propertyEngineerPhone }}</el-descriptions-item><el-descriptions-item label="商管负责人">{{ row.commercialManagerName }} {{ row.commercialManagerPhone }}</el-descriptions-item>
    </el-descriptions></el-card>
    <el-card v-if="row" shadow="never"><template #header>施工期间巡检记录</template>
      <el-empty v-if="!row.inspections?.length" description="暂无巡检记录，可扫描许可证二维码进入巡检页面" />
      <el-table v-else :data="row.inspections" border><el-table-column label="巡检类型" min-width="100"><template #default="s">{{ inspectionTypeLabel(s.row.inspectionType) }}</template></el-table-column><el-table-column prop="inspectorName" label="巡检人" min-width="100"/><el-table-column label="巡检结果" min-width="100"><template #default="s"><el-tag :type="s.row.result==='NORMAL'?'success':'danger'">{{ s.row.result==='NORMAL'?'正常':'存在问题' }}</el-tag></template></el-table-column><el-table-column prop="problemDescription" label="问题描述" min-width="180"/><el-table-column label="整改状态" min-width="100"><template #default="s">{{ rectificationLabel(s.row.rectificationStatus) }}</template></el-table-column><el-table-column label="巡检时间" min-width="165"><template #default="s">{{ formatDateTime(s.row.inspectedAt) }}</template></el-table-column><el-table-column v-if="canManageAcceptance" label="操作" width="100"><template #default="s"><el-button v-if="s.row.rectificationStatus==='PENDING'" link type="primary" @click="closeInspection(s.row.id)">确认整改</el-button></template></el-table-column></el-table>
    </el-card>
    <el-card v-if="row" shadow="never"><template #header>验收记录与报告</template><el-empty v-if="!row.acceptances?.length" description="尚未提交验收申请" /><div v-for="item in row.acceptances" :key="item.id" class="acceptance-report"><div class="report-title">第 {{ item.roundNo }} 次验收 · {{ acceptanceStatus(item) }}</div><el-descriptions :column="descriptionColumns" border><el-descriptions-item label="实际完工时间">{{ formatDateTime(item.actualCompletionTime) }}</el-descriptions-item><el-descriptions-item label="申请人">{{ item.requestedBy }}</el-descriptions-item><el-descriptions-item label="申请时间">{{ formatDateTime(item.requestedAt) }}</el-descriptions-item><el-descriptions-item label="验收人">{{ item.inspectedBy || '-' }}</el-descriptions-item><el-descriptions-item label="验收时间">{{ formatDateTime(item.inspectedAt) }}</el-descriptions-item><el-descriptions-item label="验收结果">{{ item.result==='QUALIFIED'?'合格':item.result==='REJECTED'?'不合格':'待验收' }}</el-descriptions-item><el-descriptions-item label="申请说明" :span="descriptionColumns">{{ item.applicationNote || '-' }}</el-descriptions-item><el-descriptions-item label="验收意见" :span="descriptionColumns">{{ item.resultNote || '-' }}</el-descriptions-item><el-descriptions-item label="验收照片" :span="descriptionColumns"><div class="photo-list"><a v-for="photo in acceptancePhotos(item.id)" :key="photo.id" :href="photoUrl(photo.id)" target="_blank"><img :src="photoUrl(photo.id)" :alt="photo.fileName"/></a><span v-if="!acceptancePhotos(item.id).length">-</span></div></el-descriptions-item></el-descriptions></div><el-button v-if="row.acceptances?.length" class="print-report" @click="printReport">打印验收报告</el-button>
    </el-card>
    <el-dialog v-model="acceptanceVisible" title="提交验收申请" width="520px"><el-form label-position="top"><el-form-item label="实际完工时间"><el-date-picker v-model="acceptance.actualCompletionTime" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" format="YYYY-MM-DD HH:mm" style="width:100%"/></el-form-item><el-form-item label="申请说明"><el-input v-model="acceptance.applicationNote" type="textarea" :rows="4" maxlength="1000"/></el-form-item><el-form-item label="完工照片"><input type="file" accept="image/jpeg,image/png" multiple @change="selectAcceptanceFiles"/><small>已选择 {{ acceptanceFiles.length }} 张</small></el-form-item></el-form><template #footer><el-button @click="acceptanceVisible=false">取消</el-button><el-button type="primary" @click="requestAcceptance">提交验收申请</el-button></template></el-dialog>
    <el-dialog v-model="decisionVisible" title="填写验收结果" width="520px"><el-form label-position="top"><el-form-item label="验收结果"><el-radio-group v-model="decision.result"><el-radio value="QUALIFIED">验收合格</el-radio><el-radio value="REJECTED">验收不合格</el-radio></el-radio-group></el-form-item><el-form-item label="验收意见"><el-input v-model="decision.resultNote" type="textarea" :rows="4" maxlength="1000"/></el-form-item></el-form><template #footer><el-button @click="decisionVisible=false">取消</el-button><el-button type="primary" @click="decideAcceptance">确认验收结果</el-button></template></el-dialog>
  </div>
</template>
<script setup lang="ts">
import { computed, onMounted, onBeforeUnmount, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { constructionApi, type ConstructionWorkflow } from '@/api/construction'
import { useUserStore } from '@/stores/user'
import { formatDateTime } from '@/utils/format'
const route=useRoute(),router=useRouter(),userStore=useUserStore(),row=ref<ConstructionWorkflow>(),attachments=ref<any[]>([]),loading=ref(false),acceptanceVisible=ref(false),decisionVisible=ref(false)
const acceptance=reactive({actualCompletionTime:'',applicationNote:''}),decision=reactive({result:'QUALIFIED',resultNote:''}),isMobile=ref(window.innerWidth<=768)
const acceptanceFiles=ref<File[]>([])
const descriptionColumns=computed(()=>isMobile.value?1:3),canCreate=computed(()=>userStore.hasPermission('construction.create')),canDelete=computed(()=>userStore.hasPermission('construction.delete'))
const canRequestAcceptance=computed(()=>userStore.hasPermission('construction.acceptance.request')||userStore.hasPermission('construction.manage')),canManageAcceptance=computed(()=>userStore.hasPermission('construction.acceptance.manage')||userStore.hasPermission('construction.manage'))
const locationLabel=computed(()=>`${row.value?.floorName||row.value?.floorCode||'未设置楼层'} · ${row.value?.stallCode||'-'}`),effectHint=computed(()=>row.value?.status==='ARCHIVED'?'验收已合格，铺位状态已更新，施工流程已归档。':row.value?.status==='PENDING_ACCEPTANCE'?'施工已申请验收，等待验收人员处理。':row.value?.status==='REJECTED'?'上次验收不合格，整改后可再次发起验收。':'施工进行中，可使用许可证二维码记录安保、工程和保洁巡检。')
function typeLabel(v:string){return v==='MERCHANT_CONSTRUCTION_ENTRY'?'入场装修申请':v==='MERCHANT_CONSTRUCTION_EXIT'?'撤场施工申请':'历史施工验收'} function statusLabel(v?:string){return({IN_PROGRESS:'施工中',PENDING_ACCEPTANCE:'待验收',REJECTED:'验收不合格',ARCHIVED:'已归档',CANCELLED:'已取消',DRAFT:'历史草稿',COMPLETED:'历史已完成'}as any)[v||'']||v||'-'} function statusType(v:string):any{return v==='ARCHIVED'?'success':v==='REJECTED'?'danger':v==='PENDING_ACCEPTANCE'?'warning':v==='CANCELLED'?'info':'primary'}
function stallStatusLabel(v?:string){return({AVAILABLE:'空置',RENOVATING:'装修中',EXIT_CONSTRUCTION:'撤场施工中',OCCUPIED:'在用',MAINTENANCE:'维护',DECOMMISSIONED:'停用'}as any)[v||'']||v||'-'} function inspectionTypeLabel(v:string){return({SECURITY:'安保巡检',ENGINEERING:'工程巡检',CLEANING:'保洁巡检'}as any)[v]||v} function rectificationLabel(v:string){return({NONE:'无需整改',PENDING:'待整改',COMPLETED:'已整改'}as any)[v]||v} function acceptanceStatus(v:any){return v.status==='PENDING'?'待验收':v.result==='QUALIFIED'?'验收合格':'验收不合格'}
function acceptancePhotos(id:number){return attachments.value.filter(item=>item.deviceId===id&&['COMPLETION','ACCEPTANCE'].includes(item.photoType))} function photoUrl(id:number){return `/api/v1/construction-public/${row.value?.publicToken}/attachments/${id}`}
async function load(){loading.value=true;try{row.value=await constructionApi.get(Number(route.params.id)) as any;attachments.value=await constructionApi.attachments(Number(route.params.id)) as any}finally{loading.value=false}} async function cancel(){await ElMessageBox.confirm('取消后将恢复铺位申请前状态，确认继续？','取消流程',{type:'warning'});await constructionApi.cancel(Number(route.params.id));ElMessage.success('流程已取消');await load()} function selectAcceptanceFiles(event:Event){acceptanceFiles.value=Array.from((event.target as HTMLInputElement).files||[])} async function requestAcceptance(){if(!acceptance.actualCompletionTime){ElMessage.warning('请选择实际完工时间');return}const result:any=await constructionApi.requestAcceptance(Number(route.params.id),acceptance);for(const file of acceptanceFiles.value)await constructionApi.uploadAttachment(Number(route.params.id),'ACCEPTANCE',result.id,'COMPLETION',file);acceptanceFiles.value=[];acceptanceVisible.value=false;ElMessage.success('验收申请和完工照片已提交');await load()} async function decideAcceptance(){await constructionApi.decideAcceptance(Number(route.params.id),decision);decisionVisible.value=false;ElMessage.success(decision.result==='QUALIFIED'?'验收合格，流程已归档':'已登记验收不合格');await load()} async function closeInspection(id:number){await constructionApi.closeInspection(Number(route.params.id),id);ElMessage.success('整改已确认');await load()} async function reset(){await ElMessageBox.confirm('复位会恢复铺位原状态并重新打开施工流程。','复位流程',{type:'warning'});await constructionApi.reset(Number(route.params.id));ElMessage.success('流程已复位');await load()} async function remove(){await ElMessageBox.confirm('将彻底删除流程、巡检、验收和关联资料，不可恢复。','彻底删除',{type:'error',confirmButtonText:'彻底删除'});await constructionApi.permanentDelete(Number(route.params.id));ElMessage.success('流程已删除');router.replace('/construction')} function printReport(){window.print()} function resize(){isMobile.value=window.innerWidth<=768}
onMounted(()=>{window.addEventListener('resize',resize);load()});onBeforeUnmount(()=>window.removeEventListener('resize',resize))
</script>
<style scoped>.detail-page{max-width:1180px;margin:0 auto}.actions{display:flex;flex-wrap:wrap;gap:8px}.actions :deep(.el-button){margin:0}.effect-hint{margin-bottom:12px}.el-card+.el-card{margin-top:12px}.card-title{display:flex;align-items:center;justify-content:space-between}.acceptance-report+.acceptance-report{margin-top:16px}.report-title{font-weight:700;margin-bottom:10px}.photo-list{display:flex;gap:8px;flex-wrap:wrap}.photo-list img{width:100px;height:80px;object-fit:cover;border-radius:4px}.print-report{margin-top:14px}@media(max-width:768px){.detail-page{padding:12px}.page-header{display:block}.actions{margin-top:12px;display:grid;grid-template-columns:1fr 1fr}.actions :deep(.el-button){min-height:40px}.detail-page :deep(.el-descriptions__label){width:118px}.detail-page :deep(.el-descriptions__cell){word-break:break-word}}@media print{.page-header,.effect-hint,.actions,.print-report{display:none!important}.el-card{border:none!important}.el-card:not(:last-of-type){display:none!important}}</style>
